import numpy as npimport matplotlib.pyplot as plt# import matplotlib.pyplot as pltdef stft(audio, hop_size, winLen, n_fft=None, return_complex=False):    """    Compute Short-Time Fourier Transform        Parameters:    -----------    audio : numpy array        Audio signal (1D)    hop_size : int        Hop length in samples    winLen : int        Window length in samples    n_fft : int, optional        FFT size (default: winLen)    return_complex : bool        If True, return complex values; if False, return magnitude        Returns:    --------    stft_result : numpy array        STFT result, shape (N, n_fft//2 + 1)        Complex if return_complex=True, magnitude otherwise    """        if n_fft is None:        n_fft = winLen        # Calculate number of frames    N = (len(audio) - winLen) // hop_size + 1        # Zero-padding for last frame    last_frame_end = (N - 1) * hop_size + winLen    if last_frame_end > len(audio):        padding_needed = last_frame_end - len(audio)        audio = np.pad(audio, (0, padding_needed), mode='constant')        # Extract frames    VecFrames = np.zeros((N, winLen))    for ff in range(N):        VecFrames[ff, :] = audio[ff * hop_size : ff * hop_size + winLen]        # Apply window    window = np.hamming(winLen)    VecFrames = VecFrames * window        # Compute FFT    stft_result = np.fft.rfft(VecFrames, n=n_fft, axis=1)        # Return complex or magnitude    if return_complex:        return stft_result    else:        return np.abs(stft_result)def RMSEng(audio, hop_size, winLen):    N = (len(audio)-winLen)//hop_size + 1    VecFrames = np.zeros((N,winLen))    RMSE_Eng = np.zeros((N,1))        # Zero-padding for last frame if needed    last_frame_end = (N - 1) * hop_size + winLen    if last_frame_end > len(audio):        padding_needed = last_frame_end - len(audio)        audio = np.pad(audio, (0, padding_needed), mode='constant')    for ff in range(0,N):        frame =  audio[ff*hop_size: ff*hop_size+winLen]        VecFrames[ff,:] = frame    window = np.hamming(winLen)        VecFrames = VecFrames * window    RMSE_Eng = np.sqrt(np.sum(VecFrames**2, axis=1)/winLen)    return RMSE_Engdef plot_comparison_spectrograms(emotion_data, target_emotions, hop_length=512,                                  win_length=2048, freq_range=(0, 4000)):    """    Plot spectrograms for multiple emotions side-by-side    """        n_emotions = len(target_emotions)    fig, axes = plt.subplots(n_emotions, 1, figsize=(14, 4*n_emotions))        if n_emotions == 1:        axes = [axes]        for idx, emotion in enumerate(target_emotions):        data = emotion_data[emotion]        audio = data['audio']        sr = data['sample_rate']                # Compute STFT        stft_mag = stft(audio, hop_length, win_length)        spectrogram_db = 20 * np.log10(stft_mag + 1e-10)                # Time and frequency axes        duration = len(audio) / sr        time_axis = np.linspace(0, duration, stft_mag.shape[1])        freq_axis = np.linspace(0, sr / 2, stft_mag.shape[0])                # Plot        img = axes[idx].imshow(spectrogram_db,                               aspect='auto',                               origin='lower',                               extent=[0, duration, 0, sr/2],                               cmap='viridis')                # Colorbar        cbar = plt.colorbar(img, ax=axes[idx], format='%+2.0f dB')        cbar.set_label('dB', rotation=270, labelpad=15)                # Labels        axes[idx].set_xlabel('Time (s)')        axes[idx].set_ylabel('Frequency (Hz)')        axes[idx].set_title(f'Spectrogram - {emotion.capitalize()} ({data["filename"]})')        axes[idx].set_ylim(freq_range)        axes[idx].grid(True, alpha=0.3, linestyle='--')        plt.tight_layout()    plt.show()def Mfcc(audio, sample_rate, winLen, M, n_fft=None):    """    This function calculates the MFCC             """    # frame and window the audio    if n_fft is None:        n_fft = winLen        # preemphasis the audio signal    pre_emp = 0.97    audio = np.append(audio[0], audio[1:] - pre_emp*audio[:-1])    # Calculate number of frames    hop_size = 200    N = (len(audio) - winLen) // hop_size + 1        # Zero-padding for last frame    last_frame_end = (N - 1) * hop_size + winLen    if last_frame_end > len(audio):        padding_needed = last_frame_end - len(audio)        audio = np.pad(audio, (0, padding_needed), mode='constant')        # Extract frames    VecFrames = np.zeros((N, winLen))    for ff in range(N):        VecFrames[ff, :] = audio[ff * hop_size : ff * hop_size + winLen]        # Apply window    window = np.hamming(winLen)    VecFrames = VecFrames * window        # Compute FFT    stft_result = np.fft.rfft(VecFrames, n=n_fft, axis=1)        # power pectrum    stft_dB = np.abs(stft_result)**2        # calculate the M Mel filter banks    # mel = 2595 * log10(1 + f / 700)    fmin = 0    fmax = sample_rate/2    mel_min = fmin    mel_max = 2595 * np.log10(1 + fmax / 700)    mel_peaks = np.linspace(mel_min, mel_max,M+2)    Hz_peaks = MeltoHz(mel_peaks)        # calculate the bin size    if n_fft is None:        bin_size=sample_rate/winLen    else:        bin_size=sample_rate/n_fft    # corresponding bin index    bin_idx = np.floor(Hz_peaks/bin_size).astype(int)    # number of filters    n_filter = M    # number of bins    n_fftbins = n_fft//2 +1     # now for the filter bank        filterbank = np.zeros((n_filter,n_fftbins)) # positive and negative slope filter        for idx in range(n_filter):        left = bin_idx[idx]        center = bin_idx[idx+1]        right = bin_idx[idx+2]        # positive slopes        for i in range(left, center):            if i < n_fftbins:                filterbank[idx,i]  = (i-left)/(center-left)                    for j in range(center, right):            if i < n_fftbins:                filterbank[idx,j]  = (j-right)/(center-right)                    # IMPROVEMENT 1: Normalize filterbank by area (like librosa)    # This ensures energy is preserved    enorm = 2.0 / (Hz_peaks[2:M+2] - Hz_peaks[:M])    filterbank = filterbank * enorm[:, np.newaxis]                # apply filter-bank for to the spectrum    mel_spectrum = np.dot(stft_dB, np.transpose(filterbank))        # taking log of the mel spectrum    mel_db = 10*np.log10(mel_spectrum+1e-10)    # DCT- Discreate Cosine transform    cosineBasic = np.zeros((13,n_filter))    for i in range(0,13):        for j in range(0,n_filter):            cosineBasic[i,j] =  np.cos(np.pi*i*(j+0.5)/n_filter)        # IMPROVEMENT 4: Normalize DCT (orthogonal normalization)        if i == 0:            cosineBasic[i, :] *= np.sqrt(1.0 / M)        else:            cosineBasic[i, :] *= np.sqrt(2.0 / M)            # apply the cosine basic to the mel output        mel_coff = np.dot(mel_db, cosineBasic.T)                              return mel_coffdef MeltoHz(mel):    Hz = 700*(10**(mel/2595) - 1)    return Hz# f = 500# fs= 1500# T = 1/fs# L = 1024# t = np.linspace(0,0.1, 1024)# angles = 2*np.pi*f*t# frame = np.sin(angles)# plt.plot(t, frame)# plt.xlabel('time')# plt.ylabel('magnitude')# plt.show()# fft = np.fft.fft(frame, 1024)# fft = np.fft.fftshift(fft)# freq = np.linspace(-1000, 1000, 1024)# plt.plot(freq, np.abs(fft))# plt.xlabel('freq')# plt.ylabel('magnitude')# plt.show()# stft_array = stft(frame, 256, 128)